package triggerdev.models

import io.github.thibaultmeyer.cuid.CUID
import org.jetbrains.exposed.v1.core.ReferenceOption
import org.jetbrains.exposed.v1.core.dao.id.IdTable
import org.jetbrains.exposed.v1.json.jsonb
import java.time.Instant
import java.time.temporal.ChronoUnit

object PersonalAccessTokenTable : IdTable<String>("\"PersonalAccessToken\"") {
    override val id = text("id").clientDefault { CUID.randomCUID1().toString() }.entityId()

    /** If generated by the CLI this will be "cli", otherwise user-provided */
    val name = text("name")

    /** This is the token encrypted using the ENCRYPTION_KEY */
    val encryptedToken = jsonb<String>("encryptedToken", { it }, { it })

    /** This is shown in the UI, with ******** */
    val obfuscatedToken = text("obfuscatedToken")

    /** This is used to find the token in the database */
    val hashedToken = text("hashedToken").uniqueIndex("\"PersonalAccessToken_hashedToken_key\"")
    val userId =
        reference(
            "userId",
            UserTable,
            onDelete = ReferenceOption.RESTRICT,
            onUpdate = ReferenceOption.CASCADE,
            fkName = "\"PersonalAccessToken_userId_fkey\"",
        )
    val revokedAt = pgTimestamp("revokedAt", 3).nullable()
    val lastAccessedAt = pgTimestamp("lastAccessedAt", 3).nullable()

    /** After this the token no longer authenticates. Null means it never expires. */
    val expiresAt = pgTimestamp("expiresAt", 3).nullable()

    /**
     * Set on CLI login tokens: they stop authenticating this many seconds after their last use
     * (or creation, if never used). Null means no idle limit.
     */
    val idleTimeoutSeconds = integer("idleTimeoutSeconds").nullable()

    /** When the "about to expire" email was sent. Set before sending, so it's sent at most once. */
    val expiryReminderSentAt = pgTimestamp("expiryReminderSentAt", 3).nullable()

    /** When the "has expired" email was sent. Set before sending, so it's sent at most once. */
    val expiredNoticeSentAt = pgTimestamp("expiredNoticeSentAt", 3).nullable()
    val createdAt = pgTimestamp("createdAt", 3).databaseDefault("CURRENT_TIMESTAMP") { Instant.now().truncatedTo(ChronoUnit.MILLIS) }
    val updatedAt = pgTimestamp("updatedAt", 3).clientDefault { Instant.now().truncatedTo(ChronoUnit.MILLIS) }
    val oauthClientId =
        optReference(
            "oauthClientId",
            OAuthClientTable,
            onDelete = ReferenceOption.RESTRICT,
            onUpdate = ReferenceOption.CASCADE,
            fkName = "\"PersonalAccessToken_oauthClientId_fkey\"",
        )
    override val primaryKey = PrimaryKey(id, name = "\"PersonalAccessToken_pkey\"")

    init {
        index("\"PersonalAccessToken_userId_idx\"", false, userId)
        index("\"PersonalAccessToken_oauthClientId_userId_idx\"", false, oauthClientId, userId)
    }
}
